import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr029113Xc9b6efController {
  @Put('/approval-documents/:approvalDocumentId/approval-lines')
  async replaceApprovalLines(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const documentId = req.params['approvalDocumentId'];
    if (!/^[0-9]+$/.test(documentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    // 가정: 본문은 {lines: [{approverId, lineGroup, sequenceNo}]} 형태이며, 없으면 본문 자체를 결재선 한 건으로 본다.
    const lines: unknown[] = Array.isArray(data['lines']) ? (data['lines'] as unknown[]) : [data];
    const isPositiveInt = (v: unknown): boolean => {
      if (v === null || v === undefined || v === '' || typeof v === 'boolean') {
        return false;
      }
      const n = Number(v);
      return Number.isInteger(n) && n > 0;
    };
    const hasApprover = lines.some((l) => {
      const row = l as Record<string, unknown> | null;
      return !!row && typeof row === 'object' && row['approverId'] !== undefined && row['approverId'] !== null && row['approverId'] !== '';
    });
    if (!hasApprover) {
      throw new ApiError(422, 'APPROVER_REQUIRED', '결재자가 없는 결재선은 저장할 수 없습니다.');
    }
    const seen = new Set<string>();
    const cleaned: { approverId: string; lineGroup: string; sequenceNo: string }[] = [];
    for (const l of lines) {
      const row = l as Record<string, unknown> | null;
      if (!row || typeof row !== 'object') {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재선 형식이 올바르지 않습니다.');
      }
      if (!isPositiveInt(row['approverId'])) {
        throw new ApiError(422, 'APPROVER_REQUIRED', '결재자가 없는 결재선은 저장할 수 없습니다.');
      }
      if (!isPositiveInt(row['lineGroup']) || !isPositiveInt(row['sequenceNo'])) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재선 구분과 결재 순서는 1 이상의 정수여야 합니다.');
      }
      const key = Number(row['lineGroup']) + ':' + Number(row['sequenceNo']);
      if (seen.has(key)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 결재선 구분에 결재 순서가 중복되었습니다.');
      }
      seen.add(key);
      cleaned.push({
        approverId: String(Number(row['approverId'])),
        lineGroup: String(Number(row['lineGroup'])),
        sequenceNo: String(Number(row['sequenceNo'])),
      });
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM approval_document WHERE approval_document_id = CAST(:documentId AS bigint)',
        { documentId },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '대상 결재문서를 찾을 수 없습니다.');
      }
      if (docs[0]['approvalStatus'] !== '기안') {
        throw new ApiError(409, 'APPROVAL_ALREADY_IN_PROGRESS', '결재가 시작된 문서의 결재선은 수정할 수 없습니다.');
      }
      for (const c of cleaned) {
        const found = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:approverId AS bigint)',
          { approverId: c.approverId },
        );
        if (found.length === 0) {
          throw new ApiError(404, 'APPROVER_NOT_FOUND', '조직도에 없는 사용자는 결재자로 지정할 수 없습니다.');
        }
      }
      await db.execute(
        'DELETE FROM approval_line WHERE approval_document_id = CAST(:documentId AS bigint)',
        { documentId },
      );
      const items: unknown[] = [];
      for (const c of cleaned) {
        const rows = await db.query(
          'INSERT INTO approval_line (approval_document_id, approver_id, line_group, sequence_no, created_at, updated_at) ' +
            'VALUES (CAST(:documentId AS bigint), CAST(:approverId AS bigint), CAST(:lineGroup AS integer), CAST(:sequenceNo AS integer), now(), now()) ' +
            'RETURNING approval_line_id AS "approvalLineId", approver_id AS "approverId", line_group AS "lineGroup", sequence_no AS "sequenceNo"',
          { documentId, approverId: c.approverId, lineGroup: c.lineGroup, sequenceNo: c.sequenceNo },
        );
        items.push(rows[0]);
      }
      return { items, page: 0, size: items.length, total: items.length };
    });
  }
}

