import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Form,
  Field,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

interface LineInput {
  approverId: number | string;
  lineGroup: number | string;
  sequenceNo: number | string;
}

export default function FnSfr029113Xc9b6efPage({ role, notify }: PageProps) {
  const [documentId, setDocumentId] = useState<number | string>('');
  const [searched, setSearched] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState(false);
  const [lines, setLines] = useState<LineInput[]>([]);
  const size = 20;

  const { data, error, loading, reload } = useData<Page | undefined>(async () => {
    if (searched === '') {
      return undefined;
    }
    return call<Page>('GET', '/approval-lines', role, undefined, { approvalDocumentId: searched, page, size });
  }, [searched, page, role]);

  const rows: Row[] = data ? data.items : [];
  const groups = new Set(rows.map((r) => String(r['lineGroup'])));

  function openEdit() {
    const base: LineInput[] = rows.map((r) => ({
      approverId: r['approverId'] as number,
      lineGroup: r['lineGroup'] as number,
      sequenceNo: r['sequenceNo'] as number,
    }));
    setLines(base.length > 0 ? base : [{ approverId: '', lineGroup: 1, sequenceNo: 1 }]);
    setEditing(true);
  }

  function updateLine(index: number, patch: Partial<LineInput>) {
    setLines(lines.map((l, i) => (i === index ? { ...l, ...patch } : l)));
  }

  function addLine() {
    setLines([...lines, { approverId: '', lineGroup: 1, sequenceNo: lines.length + 1 }]);
  }

  function removeLine(index: number) {
    setLines(lines.filter((_, i) => i !== index));
  }

  async function save() {
    if (searched === '') {
      throw new Error('결재문서를 선택하세요.');
    }
    if (lines.length === 0 || lines.some((l) => l.approverId === '')) {
      throw new Error('결재자가 없는 결재선은 저장할 수 없습니다.');
    }
    if (lines.some((l) => l.lineGroup === '' || l.sequenceNo === '')) {
      throw new Error('결재선 구분과 결재 순서를 입력하세요.');
    }
    await call('PUT', `/approval-documents/${searched}/approval-lines`, role, { lines: lines as unknown as Row[] });
    notify('결재선을 저장했습니다.');
    setEditing(false);
    setPage(0);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>결재문서 선택</h2>
        <Field label="결재문서" required>
          <LookupSelect table="approval_document" role={role} value={documentId} onChange={setDocumentId} placeholder="문서 선택" />
        </Field>
        <Band total={data ? data.total : 0}>
          <button
            type="button"
            onClick={() => {
              setPage(0);
              setSearched(documentId);
            }}
          >
            결재선 조회
          </button>
          <button type="button" disabled={searched === ''} onClick={openEdit}>
            결재선 지정
          </button>
        </Band>
      </section>
      <section className="box span-4">
        <h2>결재선 현황</h2>
        <Tiles items={[['결재자 수', <span>{rows.length}</span>], ['결재선 수', <span>{groups.size}</span>]]} />
      </section>
      <section className="box span-8">
        <h2>결재선 목록</h2>
        {error ? <ErrorText text={error} /> : null}
        {loading ? <p>불러오는 중…</p> : null}
        <DataTable
          rows={rows}
          empty="조회된 결재선이 없습니다."
          columns={[
            { key: 'lineGroup', label: '결재선 구분', render: (r) => <Num value={r['lineGroup']} /> },
            { key: 'sequenceNo', label: '결재 순서', render: (r) => <Num value={r['sequenceNo']} /> },
            { key: 'approverId', label: '결재자', render: (r) => <RefName table="employee" role={role} value={r['approverId']} /> },
            { key: 'actionType', label: '처리 유형', render: (r) => <Badge value={r['actionType']} /> },
            { key: 'opinion', label: '결재 의견' },
            { key: 'processedAt', label: '처리 일시', render: (r) => <DateText value={r['processedAt']} time /> },
          ]}
        />
        <Pager page={page} size={size} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {editing ? (
        <Drawer title="결재선 지정" onClose={() => setEditing(false)}>
          <Form onSubmit={save} submit="저장" note="결재가 시작된 문서의 결재선은 수정할 수 없습니다.">
            {lines.map((l, i) => (
              <div key={i}>
                <Field label="결재자" required>
                  <LookupSelect table="employee" role={role} value={l.approverId} onChange={(v) => updateLine(i, { approverId: v })} placeholder="결재자 선택" />
                </Field>
                <Field label="결재선 구분" required>
                  <NumberInput value={l.lineGroup} onChange={(v) => updateLine(i, { lineGroup: v })} />
                </Field>
                <Field label="결재 순서" required>
                  <NumberInput value={l.sequenceNo} onChange={(v) => updateLine(i, { sequenceNo: v })} />
                </Field>
                <button type="button" onClick={() => removeLine(i)}>
                  삭제
                </button>
              </div>
            ))}
            <button type="button" onClick={addLine}>
              결재자 추가
            </button>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
